CREATE TABLE public.voice_platform_roles (user_id uuid PRIMARY KEY, role text NOT NULL DEFAULT 'admin');
GRANT SELECT ON public.voice_platform_roles TO authenticated; GRANT ALL ON public.voice_platform_roles TO service_role;
ALTER TABLE public.voice_platform_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY voice_own_role ON public.voice_platform_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
INSERT INTO public.voice_platform_roles(user_id) SELECT id FROM auth.users WHERE lower(email)='melo2006@gmail.com' ON CONFLICT DO NOTHING;
CREATE FUNCTION public.is_voice_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM voice_platform_roles WHERE user_id=auth.uid() AND role='admin') $$;
CREATE TABLE public.voice_organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.voice_organizations TO authenticated; GRANT ALL ON public.voice_organizations TO service_role;
ALTER TABLE public.voice_organizations ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.voice_memberships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.voice_organizations(id) ON DELETE CASCADE, user_id uuid NOT NULL, role text NOT NULL DEFAULT 'editor', UNIQUE(organization_id,user_id));
GRANT SELECT ON public.voice_memberships TO authenticated; GRANT ALL ON public.voice_memberships TO service_role;
ALTER TABLE public.voice_memberships ENABLE ROW LEVEL SECURITY;
CREATE POLICY voice_members_read ON public.voice_memberships FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_voice_admin());
CREATE FUNCTION public.can_manage_voice(_org uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_voice_admin() OR EXISTS(SELECT 1 FROM voice_memberships WHERE organization_id=_org AND user_id=auth.uid() AND role='editor') $$;
CREATE POLICY voice_org_read ON public.voice_organizations FOR SELECT TO authenticated USING(public.can_manage_voice(id));
CREATE TABLE public.voice_agents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.voice_organizations(id), slug text NOT NULL UNIQUE DEFAULT gen_random_uuid()::text, draft jsonb NOT NULL DEFAULT '{}'::jsonb, published jsonb, version integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.voice_agents TO authenticated; GRANT ALL ON public.voice_agents TO service_role;
ALTER TABLE public.voice_agents ENABLE ROW LEVEL SECURITY;
CREATE POLICY voice_agents_read ON public.voice_agents FOR SELECT TO authenticated USING(public.can_manage_voice(organization_id));
CREATE TABLE public.voice_agent_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), agent_id uuid NOT NULL REFERENCES public.voice_agents(id) ON DELETE CASCADE, kind text NOT NULL, label text NOT NULL, url text, storage_path text, status text NOT NULL DEFAULT 'pending', content text, last_error text, refreshed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.voice_agent_sources TO authenticated; GRANT ALL ON public.voice_agent_sources TO service_role;
ALTER TABLE public.voice_agent_sources ENABLE ROW LEVEL SECURITY;
CREATE POLICY voice_sources_read ON public.voice_agent_sources FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM voice_agents a WHERE a.id=agent_id AND public.can_manage_voice(a.organization_id)));
CREATE TABLE public.gemini_voice_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), agent_id uuid REFERENCES public.voice_agents(id), organization_id uuid REFERENCES public.voice_organizations(id), lead_id uuid REFERENCES public.leads(id), prospect_id uuid REFERENCES public.prospects(id), visitor_hash text NOT NULL, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL DEFAULT now()+interval '2 minutes', consumed boolean NOT NULL DEFAULT false, config jsonb NOT NULL, max_seconds integer NOT NULL DEFAULT 300, status text NOT NULL DEFAULT 'authorized', started_at timestamptz, ended_at timestamptz, duration_seconds integer, transcript jsonb NOT NULL DEFAULT '[]'::jsonb, last_error text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.gemini_voice_sessions TO authenticated; GRANT ALL ON public.gemini_voice_sessions TO service_role;
ALTER TABLE public.gemini_voice_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY voice_sessions_read ON public.gemini_voice_sessions FOR SELECT TO authenticated USING(public.is_voice_admin() OR public.can_manage_voice(organization_id));
CREATE FUNCTION public.authorize_gemini_session(_visitor text, _token text, _config jsonb, _agent uuid DEFAULT NULL, _org uuid DEFAULT NULL, _lead uuid DEFAULT NULL, _prospect uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE g voice_guardrails; sid uuid; BEGIN PERFORM pg_advisory_xact_lock(761084); SELECT * INTO g FROM voice_guardrails LIMIT 1; IF g.enabled THEN IF (SELECT count(*) FROM gemini_voice_sessions WHERE created_at >= date_trunc('day',now()))+(SELECT count(*) FROM demo_call_attempts WHERE allowed AND created_at>=date_trunc('day',now())) >= g.max_calls_per_day_total THEN RAISE EXCEPTION 'Daily voice limit reached'; END IF; IF (SELECT count(*) FROM gemini_voice_sessions WHERE visitor_hash=_visitor AND created_at>=date_trunc('day',now())) >= g.max_calls_per_visitor_per_day THEN RAISE EXCEPTION 'Your daily voice limit has been reached'; END IF; END IF; INSERT INTO gemini_voice_sessions(visitor_hash,token_hash,config,agent_id,organization_id,lead_id,prospect_id,max_seconds) VALUES(_visitor,_token,_config,_agent,_org,_lead,_prospect,least(coalesce(g.max_call_seconds,300),3600)) RETURNING id INTO sid; RETURN sid; END $$;
REVOKE ALL ON FUNCTION public.authorize_gemini_session(text,text,jsonb,uuid,uuid,uuid,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.authorize_gemini_session(text,text,jsonb,uuid,uuid,uuid,uuid) TO service_role;
CREATE FUNCTION public.consume_gemini_session(_token text) RETURNS SETOF public.gemini_voice_sessions LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ UPDATE gemini_voice_sessions SET consumed=true,status='connecting',started_at=now() WHERE token_hash=_token AND NOT consumed AND expires_at>now() RETURNING * $$;
REVOKE ALL ON FUNCTION public.consume_gemini_session(text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.consume_gemini_session(text) TO service_role;
CREATE TABLE public.voice_agent_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), agent_id uuid NOT NULL REFERENCES public.voice_agents(id), version integer NOT NULL, config jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.voice_agent_versions TO authenticated; GRANT ALL ON public.voice_agent_versions TO service_role;
ALTER TABLE public.voice_agent_versions ENABLE ROW LEVEL SECURITY;
CREATE POLICY voice_versions_read ON public.voice_agent_versions FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM voice_agents a WHERE a.id=agent_id AND public.can_manage_voice(a.organization_id)));
CREATE POLICY voice_private_uploads_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='lead-uploads' AND (storage.foldername(name))[1]='voice' AND EXISTS(SELECT 1 FROM voice_agents a WHERE a.id::text=(storage.foldername(name))[2] AND public.can_manage_voice(a.organization_id)));
CREATE POLICY voice_private_uploads_select ON storage.objects FOR SELECT TO authenticated USING(bucket_id='lead-uploads' AND (storage.foldername(name))[1]='voice' AND EXISTS(SELECT 1 FROM voice_agents a WHERE a.id::text=(storage.foldername(name))[2] AND public.can_manage_voice(a.organization_id)));